class Solution {
public:
    int numPrimeArrangements(int n) {
        long long MOD = 1e9 + 7;
        auto is_prime = [](int x) -> bool {
            if (x < 2) return false;
            for (int d = 2; d * d <= x; ++d) {
                if (x % d == 0) return false;
            }
            return true;
        };

        int p = 0;
        for (int i = 1; i <= n; ++i) {
            if (is_prime(i)) p++;
        }
        int non_p = n - p;

        long long res = 1;
        for (int i = 1; i <= p; ++i) res = (res * i) % MOD;
        for (int i = 1; i <= non_p; ++i) res = (res * i) % MOD;
        return res;
    }
};

class Solution {
    boolean isPrime(int x) {
        if (x < 2) return false;
        for (int d = 2; d * d <= x; d++) {
            if (x % d == 0) return false;
        }
        return true;
    }

    public int numPrimeArrangements(int n) {
        long MOD = 1_000_000_007L;
        int p = 0;
        for (int i = 1; i <= n; i++) {
            if (isPrime(i)) p++;
        }
        int nonP = n - p;

        long res = 1;
        for (int i = 1; i <= p; i++) res = (res * i) % MOD;
        for (int i = 1; i <= nonP; i++) res = (res * i) % MOD;
        return (int) res;
    }
}

var numPrimeArrangements = function(n) {
    const MOD = 1000000007n;
    const isPrime = (x) => {
        if (x < 2) return false;
        for (let d = 2; d * d <= x; d++) {
            if (x % d === 0) return false;
        }
        return true;
    };

    let p = 0;
    for (let i = 1; i <= n; i++) {
        if (isPrime(i)) p++;
    }
    const nonP = n - p;

    let res = 1n;
    for (let i = 1n; i <= BigInt(p); i++) res = (res * i) % MOD;
    for (let i = 1n; i <= BigInt(nonP); i++) res = (res * i) % MOD;
    return Number(res);
};
